style.css:
body {
  background-color: #000;
  color: #fff;
}

button, a {
  background-color: #333;
  color: #fff;
  border: none;
  padding: 10px 20px;
  font-size: 16px;
  cursor: pointer;
}

button:hover, a:hover {
  background-color: #444;
}

header {
  background-color: #fff;
  padding: 20px;
}

header img {
  width: 150px;
  height: 50px;
  margin-bottom: 10px;
}

header h1 {
  color: #333;
}

button[type="submit"] {
  background-color: #007bff;
  color: #fff;
  padding: 10px 20px;
  font-size: 16px;
  border: none;
  cursor: pointer;
}

button[type="submit"]:hover {
  background-color: #0069d9;
}
